    threadTwist : f32,
    fiberDetail : f32,
    fuzziness : f32,
    weaveTightness : f32,
    threadUnevenness : f32,
    weaveImperfection : f32,
    padding1 : f32,
    fbmOctaves : f32,
    fbmAmplitude : f32,
    noiseFrequency : f32,
    colorVariation : f32,
    warpSheen : f32,
    weftSheen : f32,
